const test = require('node:test');
const assert = require('node:assert/strict');
const app = require('../lib/status-pair.cjs');
const { EventEmitter } = require('node:events');
function bounded(promise) {
  let timer;
  return Promise.race([promise,new Promise((_,reject)=>{
    timer=setTimeout(()=>reject(new Error('event wait did not settle')),1200);
  })]).finally(()=>clearTimeout(timer));
}
test('events in one nextTick batch, including reversed order', async () => {
  for (const reverse of [false,true]) {
    const emitter=new EventEmitter(); const pending=app.waitForStatus(emitter);
    process.nextTick(()=>{
      if(reverse) { emitter.emit('complete',29,'ok'); emitter.emit('ready',11); }
      else { emitter.emit('ready',11); emitter.emit('complete',29,'ok'); }
    });
    assert.deepEqual(await bounded(pending),{ready:[11],complete:[29,'ok']});
  }
});
test('error while waiting rejects with the original object', async () => {
  const emitter=new EventEmitter(); const error=new Error('socket closed');
  const check=assert.rejects(bounded(app.waitForStatus(emitter)),e=>e===error);
  process.nextTick(()=>emitter.emit('error',error)); await check;
});
test('an empty event payload remains an empty argument array', async () => {
  const emitter=new EventEmitter(); const pending=app.waitForStatus(emitter);
  emitter.emit('ready'); emitter.emit('complete',null,0,false);
  assert.deepEqual(await bounded(pending),{ready:[],complete:[null,0,false]});
});

