const test = require('node:test');
const assert = require('node:assert/strict');
const { EventEmitter } = require('node:events');
const { waitForStatus } = require('../lib/status-pair.cjs');
async function bounded(promise) {
  let timer;
  try { return await Promise.race([promise, new Promise((_,reject) => {
    timer = setTimeout(() => reject(new Error('abort did not settle')), 2500);
  })]); } finally { clearTimeout(timer); }
}
test('cancel both waits or the one still pending without removing unrelated listeners', async () => {
  for (const completed of [null, 'ready', 'complete']) {
    const emitter = new EventEmitter(); const controller = new AbortController();
    const unrelated = () => {};
    emitter.on('ready', unrelated);
    const check = assert.rejects(bounded(waitForStatus(emitter, controller.signal)), {name:'AbortError'});
    if (completed) emitter.emit(completed, 7);
    controller.abort(); await check;
    assert.deepEqual(emitter.listeners('ready'), [unrelated]);
    assert.equal(emitter.listenerCount('complete'), 0);
    assert.equal(emitter.listenerCount('error'), 0);
  }
});
test('already aborted signal', async () => {
  const emitter = new EventEmitter(); const controller = new AbortController();
  controller.abort();
  await assert.rejects(bounded(waitForStatus(emitter, controller.signal)), {name:'AbortError'});
  assert.equal(emitter.listenerCount('ready'), 0);
  assert.equal(emitter.listenerCount('complete'), 0);
});

